import { ConsistencyError, Microflows, StudioProApi } from "@mendix/extensions-api";
import {
    AGENT_RESERVED_ERROR_CODES,
    ENTITY_NOT_FOUND_ERROR_CODE,
    ENTITY_REQUIRED_ERROR_CODE,
    MODEL_NOT_FOUND_ERROR_CODE,
    MODEL_REQUIRED_ERROR_CODE,
    TOOL_MICROFLOW_EXCLUDED_ERROR_CODE,
    TOOL_MICROFLOW_RETURN_TYPE_ERROR_CODE,
    TOOL_NOT_FOUND_ERROR_CODE,
    USER_PROMPT_REQUIRED_ERROR_CODE,
} from "../../constants/consistencyCodes";
import { modelDocumentTypeId } from "../../main";
import { Agent } from "../../types/agent";
import { ConsistencyCheckResult } from "../../types/generic";
import { Tool } from "../../types/tool";
import { getCustomBlobDocumentByQualifiedName } from "../../utils/customBlobDocumentUtils";
import { getToolByQualifiedName, getToolId, getToolLabel, isMicroflowTool } from "../../utils/toolUtils";

export const registerAgentConsistencyChecks = (studioPro: StudioProApi) => ({
    check: async (document: Agent) => {
        const modelResult = await checkModel(studioPro, document);
        const entityResult = await checkEntity(studioPro, document);
        const userPromptResult = checkUserPrompt(document);
        const toolsResult = await checkTools(studioPro, document);

        return {
            errors: [...modelResult.errors, ...entityResult.errors, ...userPromptResult.errors, ...toolsResult.errors],
            dependentElementIds: [
                ...modelResult.dependentElementIds,
                ...entityResult.dependentElementIds,
                ...userPromptResult.dependentElementIds,
                ...toolsResult.dependentElementIds,
            ],
        };
    },
    reservedErrorCodes: AGENT_RESERVED_ERROR_CODES,
});

async function checkModel(studioPro: StudioProApi, document: Agent): Promise<ConsistencyCheckResult> {
    const errors: ConsistencyError[] = [];
    const dependentElementIds: string[] = [];

    if (!document.model) {
        errors.push({
            elementText: "Model",
            errorCode: MODEL_REQUIRED_ERROR_CODE,
            errorDescription: "Model is required for an agent.",
            severity: "error",
        });
        return { errors, dependentElementIds };
    }

    dependentElementIds.push(document.model.documentId);

    const model = await getCustomBlobDocumentByQualifiedName(
        studioPro,
        document.model.qualifiedName,
        modelDocumentTypeId
    );

    if (!model || model.id !== document.model.documentId) {
        errors.push({
            elementText: "Model",
            errorCode: MODEL_NOT_FOUND_ERROR_CODE,
            errorDescription: `Model ${document.model.qualifiedName} could not be found.`,
            severity: "error",
        });
    }

    return { errors, dependentElementIds };
}

async function checkEntity(studioPro: StudioProApi, document: Agent): Promise<ConsistencyCheckResult> {
    const errors: ConsistencyError[] = [];
    const dependentElementIds: string[] = [];

    if (!document.entity) {
        if (document.variables.length > 0) {
            errors.push({
                elementText: "Context entity",
                errorCode: ENTITY_REQUIRED_ERROR_CODE,
                errorDescription: "Context entity is required for an agent when using variables.",
                severity: "error",
            });
        }

        return { errors, dependentElementIds: [] };
    }

    dependentElementIds.push(document.entity.documentId);

    const [entityModuleName, entityName] = document.entity.qualifiedName.split(".");
    const domainModel = await studioPro.app.model.domainModels.getDomainModel(entityModuleName);
    const entity = domainModel?.entities.find((e) => e.name === entityName);

    if (!entity) {
        errors.push({
            elementText: "Context entity",
            errorCode: ENTITY_NOT_FOUND_ERROR_CODE,
            errorDescription: `Context entity ${document.entity.qualifiedName} could not be found.`,
            severity: "error",
        });
    }

    return { errors, dependentElementIds };
}

function checkUserPrompt(document: Agent): ConsistencyCheckResult {
    const errors: ConsistencyError[] = [];

    if (!document.userPrompt) {
        errors.push({
            elementText: "User prompt",
            errorCode: USER_PROMPT_REQUIRED_ERROR_CODE,
            errorDescription: "User prompt is required for an agent.",
            severity: "error",
        });
    }

    return { errors, dependentElementIds: [] };
}

async function checkTools(studioPro: StudioProApi, document: Agent): Promise<ConsistencyCheckResult> {
    const errors: ConsistencyError[] = [];
    const dependentElementIds: string[] = [];

    for (const agentTool of document.tools) {
        dependentElementIds.push(agentTool.document.documentId);

        const tool = await getToolByQualifiedName(studioPro, agentTool.toolType, agentTool.document.qualifiedName);
        const toolLabel = getToolLabel(agentTool.toolType);
        const toolId = getToolId(tool);

        if (!tool || toolId !== agentTool.document.documentId) {
            errors.push({
                elementText: "Tools",
                errorCode: TOOL_NOT_FOUND_ERROR_CODE,
                errorDescription: `${toolLabel} ${agentTool.document.qualifiedName} could not be found.`,
                severity: "error",
            });
        } else if (isMicroflowTool(tool)) {
            const { errors: microflowErrors } = checkMicroflowTool(tool, agentTool);
            errors.push(...microflowErrors);
        }
    }

    return { errors, dependentElementIds };
}

function checkMicroflowTool(tool: Microflows.Microflow, agentTool: Tool): ConsistencyCheckResult {
    const errors: ConsistencyError[] = [];

    if (tool.excluded) {
        errors.push({
            elementText: "Tools",
            errorCode: TOOL_MICROFLOW_EXCLUDED_ERROR_CODE,
            errorDescription: `Microflow ${agentTool.document.qualifiedName} is excluded from the project and cannot be used.`,
            severity: "error",
        });
    } else if (tool.microflowReturnType.$Type !== "DataTypes$StringType") {
        errors.push({
            elementText: "Tools",
            errorCode: TOOL_MICROFLOW_RETURN_TYPE_ERROR_CODE,
            errorDescription: `Microflow ${agentTool.document.qualifiedName} must return a String.`,
            severity: "error",
        });
    }

    return { errors, dependentElementIds: [] };
}
